<?php
require_once __DIR__.'/includes/config.php'; require_login();require_permission('inventory');
$uid=(int)$_SESSION['user_id'];
$from=trim($_GET['from']??''); $to=trim($_GET['to']??''); $productId=filter_var($_GET['product_id']??'',FILTER_VALIDATE_INT); $type=trim($_GET['type']??'');
$validTypes=['opening_stock','manual_adjustment','sale']; if(!in_array($type,$validTypes,true))$type='';
$productsQ=$pdo->prepare('SELECT id,name FROM products WHERE user_id=? ORDER BY name');$productsQ->execute([$uid]);$products=$productsQ->fetchAll();
$where=['m.user_id=?'];$params=[$uid];
if($from!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$from)){$where[]='m.created_at>=?';$params[]=$from.' 00:00:00';}else $from='';
if($to!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$to)){$where[]='m.created_at<=?';$params[]=$to.' 23:59:59';}else $to='';
if($productId){$where[]='m.product_id=?';$params[]=$productId;}
if($type!==''){$where[]='m.movement_type=?';$params[]=$type;}
$sql='SELECT m.* FROM inventory_movements m WHERE '.implode(' AND ',$where).' ORDER BY m.id DESC LIMIT 500';$q=$pdo->prepare($sql);$q->execute($params);$movements=$q->fetchAll();
$sumQ=$pdo->prepare('SELECT COUNT(*) movement_count, COALESCE(SUM(CASE WHEN quantity_change>0 THEN quantity_change ELSE 0 END),0) units_added, COALESCE(SUM(CASE WHEN quantity_change<0 THEN -quantity_change ELSE 0 END),0) units_removed FROM inventory_movements m WHERE '.implode(' AND ',$where));$sumQ->execute($params);$summary=$sumQ->fetch();
$pageTitle='Stock history'; require __DIR__.'/includes/header.php'; ?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Stock history</h1><p class="muted mb-0">Audit trail for opening stock, manual adjustments, and sales deductions. Showing up to 500 latest matching movements.</p></div><a class="btn btn-outline-secondary" href="products.php">Manage products</a></div>
<div class="row g-3 mb-4"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Movements shown</div><div class="stat-value"><?=(int)$summary['movement_count']?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Units added</div><div class="stat-value text-success">+<?=(int)$summary['units_added']?></div></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Units removed</div><div class="stat-value text-danger">−<?=(int)$summary['units_removed']?></div></div></div></div>
<div class="card mb-4"><div class="card-body"><form class="row g-3 align-items-end" method="get"><div class="col-md-3"><label class="form-label">Product</label><select class="form-select" name="product_id"><option value="">All products</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" <?=((string)$productId===(string)$p['id']?'selected':'')?>><?=e($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><label class="form-label">Movement</label><select class="form-select" name="type"><option value="">All types</option><option value="opening_stock" <?=$type==='opening_stock'?'selected':''?>>Opening stock</option><option value="manual_adjustment" <?=$type==='manual_adjustment'?'selected':''?>>Manual adjustment</option><option value="sale" <?=$type==='sale'?'selected':''?>>Sale</option></select></div><div class="col-md-2"><label class="form-label">From</label><input type="date" class="form-control" name="from" value="<?=e($from)?>"></div><div class="col-md-2"><label class="form-label">To</label><input type="date" class="form-control" name="to" value="<?=e($to)?>"></div><div class="col-md-3 d-flex gap-2"><button class="btn btn-primary">Filter</button><a class="btn btn-light" href="inventory.php">Reset</a></div></form></div></div>
<div class="card"><div class="card-body"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Date</th><th>Product</th><th>Movement</th><th>Change</th><th>Before</th><th>After</th><th>Reference</th><th>Note</th></tr></thead><tbody><?php foreach($movements as $m):?><tr><td><?=date('d M Y H:i',strtotime($m['created_at']))?></td><td class="fw-semibold"><?=e($m['product_name'])?></td><td><?php $labels=['opening_stock'=>'Opening stock','manual_adjustment'=>'Manual adjustment','sale'=>'Sale'];?><span class="badge text-bg-light"><?=e($labels[$m['movement_type']]??ucwords(str_replace('_',' ',$m['movement_type'])))?></span></td><td class="fw-semibold <?=$m['quantity_change']>0?'text-success':($m['quantity_change']<0?'text-danger':'')?>"><?=$m['quantity_change']>0?'+':''?><?=(int)$m['quantity_change']?></td><td><?=(int)$m['quantity_before']?></td><td><?=(int)$m['quantity_after']?></td><td><?=e(($m['reference_type']??'—').(!empty($m['reference_id'])?' #'.$m['reference_id']:''))?></td><td><?=e($m['note']??'—')?></td></tr><?php endforeach;?></tbody></table><?php if(!$movements):?><div class="empty-state">No stock movements match these filters. New stock activity will be recorded after the Phase 3 migration is installed.</div><?php endif;?></div></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
